----- src/filter.js -----
function criterion(value) {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

export function filterIssues(issues, filters = {}) {
  const status = criterion(filters.status);
  const keyword = criterion(filters.keyword);
  if (!status && !keyword) return issues.slice();
  return issues.filter((issue) => {
    const issueStatus = typeof issue.status === "string" ? issue.status.toLowerCase() : "";
    const title = typeof issue.title === "string" ? issue.title.toLowerCase() : "";
    if (status && issueStatus !== status) return false;
    if (keyword && !title.includes(keyword)) return false;
    return true;
  });
}

----- test/filter.test.js -----
import test from "node:test";
import assert from "node:assert/strict";
import { filterIssues } from "../src/filter.js";
import { issues } from "../src/issues.js";

test("empty list stays empty", () => {
  const input = [];
  assert.deepEqual(filterIssues(input, { status: "open", keyword: "login" }), []);
  assert.deepEqual(input, []);
});

test("no match returns an empty list and leaves records unchanged", () => {
  const input = structuredClone(issues);
  const before = structuredClone(input);
  const result = filterIssues(input, { status: "open", keyword: "does-not-match" });
  assert.deepEqual(result, []);
  assert.deepEqual(input, before);
});

test("status and keyword filters combine without changing records", () => {
  const input = [
    { id: 1, title: "Login help", status: "open", owner: "Lin" },
    { id: 2, title: "Login verification", status: "pending", owner: "Chen" },
    { id: 3, title: "Invoice correction", status: "open", owner: "Mei" },
  ];
  const before = structuredClone(input);
  const result = filterIssues(input, { status: "open", keyword: "login" });
  assert.deepEqual(result.map((issue) => issue.id), [1]);
  assert.equal(result[0], input[0]);
  assert.deepEqual(input, before);
});

test("queue records stay unchanged after filtering", () => {
  const before = structuredClone(issues);
  const result = filterIssues(issues, { status: "open", keyword: "login" });
  assert.deepEqual(result.map((issue) => issue.id), [1]);
  assert.deepEqual(issues, before);
});
